import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] x = new long[n];
        for (int i = 0; i < n; i++) x[i] = nextLong();
        // dp[i]: best extra gain from disjoint swaps within x[i..]; swapping (i, i+1) gains x[i]-x[i+1]
        long[] dp = new long[n + 2];
        for (int i = n - 1; i >= 0; i--) {
            dp[i] = dp[i + 1];
            if (i + 1 < n) dp[i] = Math.max(dp[i], dp[i + 2] + Math.max(0, x[i] - x[i + 1]));
        }
        long base = 0;
        for (int i = 0; i < n; i++) base += (i + 1) * x[i];
        System.out.println(base + dp[0]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	x := make([]int64, n)
	for i := range x {
		x[i] = nextInt()
	}
	// dp[i]: best extra gain from disjoint swaps within x[i..]; swapping (i, i+1) gains x[i]-x[i+1]
	dp := make([]int64, n+2)
	for i := n - 1; i >= 0; i-- {
		dp[i] = dp[i+1]
		if i+1 < n {
			dp[i] = max(dp[i], dp[i+2]+max(0, x[i]-x[i+1]))
		}
	}
	var base int64
	for i, v := range x {
		base += int64(i+1) * v
	}
	fmt.Println(base + dp[0])
}
